134	
135	export type ModoPadrao = 'contem' | 'comeca' | 'igual';
136	
137	/** Regra de categorização; a prioridade é a posição na lista `regras`. */
138	export interface RegraCategoria {
139	  id: string;
140	  padrao: string;
141	  modo: ModoPadrao;
142	  tipo: TipoMovimento;
143	  categoriaId: string;
144	  tags: string[];
145	  ativa: boolean;
146	}
147	
148	export type ClasseAtivo = 'renda-fixa' | 'acoes' | 'fundos' | 'cripto' | 'outros';
149	
150	export interface MovimentoAtivo {
151	  id: string;
152	  tipo: 'aporte' | 'resgate';
153	  data: DataISO;
154	  /** Sempre positivo; o sinal vem do tipo. */
155	  valor: Centavos;
156	}
157	
158	/** Valor de mercado anotado para um ativo numa data. */
159	export interface MarcacaoAtivo {
160	  id: string;
161	  data: DataISO;
162	  valor: Centavos;
163	}
164	
165	/** Ativo da carteira manual de investimentos; não gera transações nem mexe em saldos. */
166	export interface Ativo {
167	  id: string;
168	  nome: string;
169	  classe: ClasseAtivo;
170	  movimentos: MovimentoAtivo[];
171	  marcacoes: MarcacaoAtivo[];
172	  criadoEm: number;
173	}
174	
175	export type TipoDivida = 'devo' | 'emprestei';
176	export type SistemaAmortizacao = 'price' | 'sac';
177	
178	/** Pagamento de dívida; sem `parcela` é uma amortização extra. */
179	export interface PagamentoDivida {
180	  id: string;
181	  data: DataISO;
182	  valor: Centavos;
183	  parcela?: number;
184	}
185	
186	/** Dívida ou empréstimo concedido; `taxaBp` é a taxa mensal em centésimos de ponto percentual (199 = 1,99%). */
187	export interface Divida {
188	  id: string;
189	  nome: string;
190	  tipo: TipoDivida;
191	  principal: Centavos;
192	  taxaBp: number;
193	  parcelas: number;
194	  primeiraParcela: DataISO;
195	  sistema: SistemaAmortizacao;
196	  pagamentos: PagamentoDivida[];
197	  criadaEm: number;
198	}
199	
200	export interface AppState {
201	  schemaVersion: number;
202	  contas: Conta[];
203	  categorias: Categoria[];
204	  transacoes: Transacao[];
205	  orcamentos: Orcamento[];
206	  metas: Meta[];
207	  recorrencias: Recorrencia[];
208	  mapeamentosCsv: Record<string, MapeamentoCsv>;
209	  importacoes: Importacao[];
210	  pagamentosFatura: PagamentoFatura[];
211	  agenda: Agendamento[];
212	  regras: RegraCategoria[];
213	  investimentos: Ativo[];
214	  dividas: Divida[];
215	}
216	
217	export type Resultado<T> = { ok: true; valor: T } | { ok: false; erro: string; campo?: string };
218	
219	export const ok = <T>(valor: T): Resultado<T> => ({ ok: true, valor });
220	export const falha = (erro: string, campo?: string): Resultado<never> => ({ ok: false, erro, campo });
