1	import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
2	import { FalhaCarregamento } from './components/FalhaCarregamento';
3	import { Layout } from './components/Layout';
4	import { DashboardPage } from './pages/DashboardPage';
5	import { CalendarioPage } from './pages/CalendarioPage';
6	import { CartoesPage } from './pages/CartoesPage';
7	import { ContasPage } from './pages/ContasPage';
8	import { ConfiguracoesPage } from './pages/ConfiguracoesPage';
9	import { DividasPage } from './pages/DividasPage';
10	import { ImportarCsvPage } from './pages/ImportarCsvPage';
11	import { InvestimentosPage } from './pages/InvestimentosPage';
12	import { MetasPage } from './pages/MetasPage';
13	import { AjudaPage } from './pages/AjudaPage';
14	import { OrcamentoPage } from './pages/OrcamentoPage';
15	import { RelatoriosPage } from './pages/RelatoriosPage';
16	import { RegrasPage } from './pages/RegrasPage';
17	import { TransacoesPage } from './pages/TransacoesPage';
18	import { useSnapshot } from './state/store';
19	
20	/** Rotas do app; separadas do roteador para poderem ser testadas com MemoryRouter. */
21	export function AppRoutes() {
22	  const { problema } = useSnapshot();
23	  if (problema) return <FalhaCarregamento problema={problema} />;
24	  return (
25	    <Routes>
26	      <Route element={<Layout />}>
27	        <Route index element={<DashboardPage />} />
28	        <Route path="/transacoes" element={<TransacoesPage />} />
29	        <Route path="/contas" element={<ContasPage />} />
30	        <Route path="/cartoes" element={<CartoesPage />} />
31	        <Route path="/calendario" element={<CalendarioPage />} />
32	        <Route path="/orcamento" element={<OrcamentoPage />} />
33	        <Route path="/metas" element={<MetasPage />} />
34	        <Route path="/regras" element={<RegrasPage />} />
35	        <Route path="/investimentos" element={<InvestimentosPage />} />
36	        <Route path="/dividas" element={<DividasPage />} />
37	        <Route path="/importar" element={<ImportarCsvPage />} />
38	        <Route path="/relatorios" element={<RelatoriosPage />} />
39	        <Route path="/configuracoes" element={<ConfiguracoesPage />} />
40	        <Route path="/dados" element={<Navigate to="/configuracoes" replace />} />
41	        <Route path="/ajuda" element={<AjudaPage />} />
42	        <Route path="*" element={<Navigate to="/" replace />} />
43	      </Route>
44	    </Routes>
45	  );
46	}
47	
48	export default function App() {
49	  return (
50	    <BrowserRouter>
51	      <AppRoutes />
52	    </BrowserRouter>
53	  );
54	}
