2	import { novoId, proximoTempo } from './id';
3	import {
4	  falha,
5	  ok,
6	  type AppState,
7	  type Ativo,
8	  type Centavos,
9	  type ClasseAtivo,
10	  type DataISO,
11	  type Mes,
12	  type MovimentoAtivo,
13	  type Resultado,
14	} from './types';
15	
16	export const ATIVO_NOME_MAX = 40;
17	export const MESES_EVOLUCAO = 12;
18	
19	export const CLASSES: { valor: ClasseAtivo; rotulo: string }[] = [
20	  { valor: 'renda-fixa', rotulo: 'Renda fixa' },
21	  { valor: 'acoes', rotulo: 'Ações' },
22	  { valor: 'fundos', rotulo: 'Fundos' },
23	  { valor: 'cripto', rotulo: 'Cripto' },
24	  { valor: 'outros', rotulo: 'Outros' },
25	];
26	
27	export const rotuloClasse = (classe: ClasseAtivo): string => CLASSES.find((c) => c.valor === classe)?.rotulo ?? classe;
28	
29	export interface DadosAtivo {
30	  nome: string;
31	  classe: ClasseAtivo;
32	}
33	
34	export interface DadosMovimento {
35	  tipo: 'aporte' | 'resgate';
36	  data: DataISO;
37	  valor: Centavos;
38	}
39	
40	export interface DadosMarcacao {
41	  data: DataISO;
42	  valor: Centavos;
43	}
44	
45	export interface Desempenho {
46	  investido: Centavos;
47	  valorAtual: Centavos;
48	  rentabilidade: Centavos;
49	  /** Percentual com uma casa decimal sobre o investido líquido; null sem investido. */
50	  rentabilidadePct: number | null;
51	}
52	
53	export interface FatiaClasse {
54	  classe: ClasseAtivo;
55	  valor: Centavos;
56	  /** Percentual com uma casa decimal; a soma das fatias é 100. */
57	  pct: number;
58	}
