65	const porData = <T extends { data: DataISO; id: string }>(a: T, b: T) => (a.data < b.data ? -1 : a.data > b.data ? 1 : 0);
66	const delta = (m: MovimentoAtivo): Centavos => (m.tipo === 'aporte' ? m.valor : -m.valor);
67	
68	/** Investido líquido (aportes menos resgates) até `ate`, inclusive. */
69	export function investidoEm(ativo: Ativo, ate?: DataISO): Centavos {
70	  return ativo.movimentos.filter((m) => ate === undefined || m.data <= ate).reduce((s, m) => s + delta(m), 0);
71	}
72	
73	/** Valor da última marcação até `ate` mais o líquido movimentado depois dela; sem marcação, o investido. */
74	export function valorEm(ativo: Ativo, ate?: DataISO): Centavos {
75	  const marcacoes = ativo.marcacoes.filter((m) => ate === undefined || m.data <= ate).sort(porData);
76	  const ultima = marcacoes[marcacoes.length - 1];
77	  if (!ultima) return investidoEm(ativo, ate);
78	  const depois = ativo.movimentos.filter((m) => m.data > ultima.data && (ate === undefined || m.data <= ate));
79	  return ultima.valor + depois.reduce((s, m) => s + delta(m), 0);
80	}
81	
82	/** Arredonda para uma casa decimal. */
83	const umaCasa = (x: number) => Math.round(x * 10) / 10;
84	
85	export function desempenho(investido: Centavos, valorAtual: Centavos): Desempenho {
86	  const rentabilidade = valorAtual - investido;
87	  return { investido, valorAtual, rentabilidade, rentabilidadePct: investido > 0 ? umaCasa((rentabilidade * 100) / investido) : null };
88	}
89	
90	export const desempenhoAtivo = (ativo: Ativo, ate?: DataISO): Desempenho => desempenho(investidoEm(ativo, ate), valorEm(ativo, ate));
91	
92	export function desempenhoCarteira(ativos: Ativo[], ate?: DataISO): Desempenho {
93	  return desempenho(
94	    ativos.reduce((s, a) => s + investidoEm(a, ate), 0),
95	    ativos.reduce((s, a) => s + valorEm(a, ate), 0),
96	  );
97	}
98	
99	/** Alocação por classe com percentuais em décimos que somam exatamente 100,0 (maiores restos). */
100	export function alocacaoPorClasse(ativos: Ativo[], ate?: DataISO): FatiaClasse[] {
101	  const totais = new Map<ClasseAtivo, Centavos>();
102	  for (const a of ativos) totais.set(a.classe, (totais.get(a.classe) ?? 0) + valorEm(a, ate));
103	  const fatias = CLASSES.map((c) => ({ classe: c.valor, valor: totais.get(c.valor) ?? 0 })).filter((f) => f.valor > 0);
104	  const total = fatias.reduce((s, f) => s + f.valor, 0);
105	  if (total === 0) return [];
106	  const brutos = fatias.map((f) => (f.valor * 1000) / total);
107	  const decimos = brutos.map(Math.floor);
108	  let faltam = 1000 - decimos.reduce((s, d) => s + d, 0);
109	  const ordem = brutos.map((b, i) => ({ i, resto: b - decimos[i] })).sort((x, y) => y.resto - x.resto || x.i - y.i);
110	  for (const { i } of ordem) {
111	    if (faltam <= 0) break;
112	    decimos[i] += 1;
113	    faltam -= 1;
114	  }
115	  return fatias.map((f, i) => ({ ...f, pct: decimos[i] / 10 })).sort((a, b) => b.valor - a.valor);
116	}
117	
118	/** Patrimônio no fim de cada mês, dos últimos `MESES_EVOLUCAO` meses a partir do primeiro movimento. */
119	export function evolucaoPatrimonio(ativos: Ativo[], hoje: DataISO): PontoPatrimonio[] {
120	  const datas = ativos.flatMap((a) => a.movimentos.map((m) => m.data));
121	  if (datas.length === 0) return [];
122	  const mesHoje = mesDe(hoje);
123	  const primeiro = mesDe(datas.reduce((a, b) => (a < b ? a : b)));
124	  const inicio = diferencaMeses(primeiro, mesHoje) >= MESES_EVOLUCAO ? somarMeses(mesHoje, -(MESES_EVOLUCAO - 1)) : primeiro;
125	  const pontos: PontoPatrimonio[] = [];
126	  for (let mes = inicio; mes <= mesHoje; mes = somarMeses(mes, 1)) {
127	    const fim = mes === mesHoje ? hoje : ultimoDia(mes);
128	    pontos.push({ mes, valor: ativos.reduce((s, a) => s + valorEm(a, fim), 0) });
129	  }
130	  return pontos;
131	}
