133	/** Menor posição acumulada ao longo do tempo; negativa significa resgate sem saldo. */
134	function posicaoMinima(movimentos: MovimentoAtivo[]): Centavos {
135	  // No mesmo dia os aportes contam antes dos resgates.
136	  const ordenados = [...movimentos].sort((a, b) => (a.data === b.data ? (a.tipo === b.tipo ? 0 : a.tipo === 'aporte' ? -1 : 1) : a.data < b.data ? -1 : 1));
137	  let soma = 0;
138	  let minimo = 0;
139	  for (const m of ordenados) {
140	    soma += delta(m);
141	    minimo = Math.min(minimo, soma);
142	  }
143	  return minimo;
144	}
