import { Cartao } from '../ui';
import { formatarMoeda } from '../../domain/money';
import { formatarPrazo, textoDataEstimada, type ParametrosIndependencia, type Simulacao, type SituacaoIdade } from '../../domain/independencia';
import './ResultadoIndependencia.css';

interface Props {
  parametros: ParametrosIndependencia;
  simulacao: Simulacao;
  idade: SituacaoIdade | null;
}

function textoIdade(p: ParametrosIndependencia, idade: SituacaoIdade): string[] {
  const linhas: string[] = [];
  if (idade.idadeNaIndependencia !== null) linhas.push(`Você terá cerca de ${idade.idadeNaIndependencia} anos ao atingir a independência.`);
  if (p.idadeAlvo === undefined || idade.folgaMeses === null && idade.aporteNecessario === null) return linhas;
  if (idade.folgaMeses !== null) {
    linhas.push(
      idade.folgaMeses >= 0
        ? `Dentro da idade alvo de ${p.idadeAlvo} anos, com ${formatarPrazo(idade.folgaMeses)} de folga.`
        : `Fora da idade alvo de ${p.idadeAlvo} anos: atraso de ${formatarPrazo(-idade.folgaMeses)}.`,
    );
  } else {
    linhas.push(`Fora da idade alvo de ${p.idadeAlvo} anos.`);
  }
  if (idade.aporteNecessario !== null) linhas.push(`Aporte mensal necessário para chegar aos ${p.idadeAlvo} anos: ${formatarMoeda(idade.aporteNecessario)}.`);
  return linhas;
}

export function ResultadoIndependencia({ parametros, simulacao, idade }: Props) {
  const linhasIdade = idade ? textoIdade(parametros, idade) : [];
  return (
    <Cartao titulo="Resultado">
      <dl className="indep-resultado__grade">
        <div className="indep-resultado__item">
          <dt>Patrimônio-alvo</dt>
          <dd data-testid="indep-alvo">{formatarMoeda(simulacao.alvo)}</dd>
        </div>
        <div className="indep-resultado__item">
          <dt>Tempo até atingir</dt>
          <dd data-testid="indep-prazo">{simulacao.meses === null ? '—' : formatarPrazo(simulacao.meses)}</dd>
        </div>
        <div className="indep-resultado__item">
          <dt>Data estimada</dt>
          <dd data-testid="indep-data">{textoDataEstimada(simulacao.mesAlvo)}</dd>
        </div>
      </dl>
      {simulacao.meses === null ? (
        <p className="indep-resultado__aviso" role="status">
          Não é alcançável em 100 anos com estas premissas. Aumente o aporte, o retorno ou a taxa de retirada, ou reduza o gasto desejado.
        </p>
      ) : simulacao.meses === 0 ? (
        <p className="indep-resultado__idade" role="status">
          Independência já atingida: seu patrimônio atual cobre o patrimônio-alvo.
        </p>
      ) : null}
      {linhasIdade.map((l) => (
        <p key={l} className="indep-resultado__idade">
          {l}
        </p>
      ))}
    </Cartao>
  );
}
